+/** Selects a supported Accept-Language preference, or the configured fallback. */
+export function requestLanguage(header, fallback = "en") {
+  if (typeof header !== "string") return fallback;
+  let selected = fallback;
+  let best = 0;
+  for (const entry of header.split(",")) {
+    const [tag, ...parameters] = entry.trim().split(";");
+    if (!/^[a-z]{2,8}(?:-[a-z0-9]{1,8})*$/i.test(tag)) continue;
+    const language = tag.toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(language)) continue;
+    let quality = 1;
+    for (const parameter of parameters) {
+      const match = /^q\s*=\s*(.*)$/i.exec(parameter.trim());
+      if (match) quality = /^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/.test(match[1]) ? Number(match[1]) : 0;
+    }
+    if (quality > best) {
+      selected = language;
+      best = quality;
+    }
+  }
+  return selected;
+}
